export const ASSEMBLY_SKETCH = "# CWA integration sketch — not runnable or a reference implementation.\n# prepare_request is your application's: producers run before assembly, and it freezes the snapshot.\n# assemble_snapshot is what a conformant assembler does with that snapshot. Use one of the\n# implementations on the Assembler page rather than writing it; it is outlined here so you know what it checks.\ndef prepare_request(req):\n    # Keep each batch whole: its items and exclusions stay bound to the producer identity\n    # your application authenticated. Never flatten items away from that identity or\n    # read identity from item.source.\n    batches = [bind_identity(authenticate(producer), producer.run(req)) for producer in producers_for(req)]\n    snapshot = freeze_snapshot(\n        batches=batches,\n        capabilities=capability_grant(req),  # Allow-list result for this route and user.\n        conflicts=declared_conflict_groups(req),  # schema/conflict_group.schema.json\n        scope=request_scope(req),\n        assembly_time=req.assembly_time,\n        route_policy=load_versioned_policy(req.route),\n        profile=load_profile('policy-first-chat/v1'),\n        tokenizer=req.tokenizer,\n        renderer=req.renderer,  # A published renderer, such as cwa-messages/v1.\n        budget=req.budget,  # input is already net of reserved_output.\n    )\n    return conformant_assembler.assemble(snapshot)\n\n\ndef assemble_snapshot(snapshot):\n    # No model calls, external reads, or ambient clock reads from this point.\n    reject_if_invalid(snapshot)  # Schemas and Snapshot checks; no payload and no trace (R-17).\n    admitted = admit(snapshot)\n    resolved = resolve_declared_conflicts(admitted, snapshot)  # R-11\n    current = supersede_stale_observations(resolved, snapshot)  # R-25\n    unique = drop_exact_duplicates(current, snapshot)  # R-24\n    capped = cap_items_per_source(unique, snapshot)  # R-26\n    fitted = fit_with_rendered_token_counts(capped, snapshot)  # Refusal checks in contract/reasons.json order.\n    if fitted.refused:\n        return refused_result(fitted.reason, snapshot)  # No payload; trace.result = null.\n    payload = render_profile(fitted, snapshot)\n    return result_with_trace_and_sha256(payload, fitted, snapshot)\n";
